export class ProductDetailComponent implements OnInit {
  products: any;
  selectedProduct: any;

  ngOnInit(): void {
    this.products = productsData;
    this.findSelectedProduct();
  }

  findSelectedProduct() {
    let url = window.location.href;
    let id = url.split('/')[4];
    this.products.forEach((product: any) => {
      if (product.id == id) {
        this.selectedProduct = product;
      }
    });
  }
}

